#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Puts the Optizzz site on a Scaleway VPS (docs/adr/0009-vps-scaleway.md): the instance, its secrets, the data brought
# over from Neon, the GitHub deployment, the backups and the optizzz.fr domain. Run from the repository root.
# Values are kept in deploy/.env.vps (git-ignored) so a re-run offers them back; the VPS keeps its own in
# /opt/optizzz/.env.

TOTAL_STAGES=11
ENV_FILE="deploy/.env.vps"
OLD_ENV="apps/web/.env.neon"
DEPLOY_KEY="$HOME/.ssh/optizzz_deploy"

# The secrets the old setup (Vercel and Neon) already generated: kept, so sessions and Discord reminders survive.
old() { grep -E "^${1}=" "$OLD_ENV" 2>/dev/null | tail -n1 | cut -d= -f2- || true; }
root() { ssh -o StrictHostKeyChecking=accept-new "root@$VPS_HOST" "$@"; }
deployer() { ssh -i "$DEPLOY_KEY" "optizzz@$VPS_HOST" "$@"; }

banner "Optizzz : passer le site sur un VPS Scaleway"

stage "Scaleway : l'instance"
say "Une seule machine pour le site, sa base Postgres, le cron horaire et les sauvegardes."
open_url "https://console.scaleway.com/instance/servers"
step "Create Instance → zone Paris (PAR 1 ou 2)."
step "Type : DEV1-S (2 vCPU, 2 Go) suffit, l'image se construit sur GitHub ; PLAY2-NANO ou DEV1-M pour plus de marge."
step "Image : Ubuntu 24.04 LTS. Volume système : 20 Go au moins (Block Storage)."
step "IPv4 publique (flexible) et votre clé SSH : vous vous connecterez en root avec elle."
note "Coût : regardez le prix affiché par la console, environ 7 à 15 € par mois selon le type."
ask VPS_HOST "Adresse IPv4 publique de l'instance :"
write_env VPS_HOST "$VPS_HOST"

stage "Scaleway : le pare-feu (groupe de sécurité)"
say "Seuls SSH, HTTP et HTTPS entrent ; Postgres n'est jamais ouvert sur Internet."
open_url "https://console.scaleway.com/instance/security-groups"
step "Le groupe de l'instance → Inbound default policy : Drop."
step "Règles entrantes Accept : TCP 22, TCP 80, TCP 443, UDP 443 (HTTP/3)."
pause "Fait ? Entrée pour continuer"

stage "Préparer la machine"
say "Docker, rclone (copie des sauvegardes), 2 Go de swap, mises à jour de sécurité automatiques,"
say "et l'utilisateur optizzz qui déploie dans /opt/optizzz avec sa propre clé SSH."
if [[ ! -f "$DEPLOY_KEY" ]]; then
  ssh-keygen -q -t ed25519 -N "" -C "optizzz-deploy" -f "$DEPLOY_KEY"
  say "Clé de déploiement créée : $DEPLOY_KEY (elle ira dans les secrets GitHub)."
fi
if confirm "Préparer root@$VPS_HOST maintenant ?"; then
  root bash -s -- "$(printf '%q' "$(cat "$DEPLOY_KEY.pub")")" <<'REMOTE'
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive
apt-get update -q
apt-get install -yq docker.io docker-compose-v2 rclone unattended-upgrades
systemctl enable --now docker
if [[ ! -f /swapfile ]]; then
  fallocate -l 2G /swapfile && chmod 600 /swapfile && mkswap /swapfile && swapon /swapfile
  echo '/swapfile none swap sw 0 0' >>/etc/fstab
fi
id optizzz >/dev/null 2>&1 || useradd --create-home --shell /bin/bash --groups docker optizzz
install -d -o optizzz -g optizzz -m 700 /home/optizzz/.ssh /opt/optizzz
echo "$1" >/home/optizzz/.ssh/authorized_keys
chown optizzz:optizzz /home/optizzz/.ssh/authorized_keys && chmod 600 /home/optizzz/.ssh/authorized_keys
docker compose version
REMOTE
else
  SKIPPED+=("préparer la machine (étape 3 de cet assistant)")
fi
pause

stage "Les secrets du site"
say "Les mots de passe de la base sont nouveaux. Les secrets du site viennent de l'ancienne installation :"
say "les garder évite de déconnecter tout le monde et de perdre les rappels Discord (chiffrés avec leur clé)."
for name in POSTGRES_PASSWORD APP_DB_PASSWORD; do
  value=$(_existing "$name" || true)
  [[ -n "$value" ]] || value=$(openssl rand -hex 24)
  write_env "$name" "$value"
done
for name in REVALIDATE_SECRET BETTER_AUTH_SECRET; do
  value=$(_existing "$name" || old "$name")
  [[ -n "$value" ]] || value=$(openssl rand -hex 32)
  write_env "$name" "$value"
done
open_url "https://vercel.com/dashboard"
step "Projet optizzz → Settings → Environment Variables (Production) : copiez les valeurs ci-dessous."
note "Ou : vercel env pull --environment=production (dans apps/web), puis lisez le fichier créé."
ask_secret BREVO_API_KEY "BREVO_API_KEY :"
write_env BREVO_API_KEY "$BREVO_API_KEY"
ask EMAIL_FROM "EMAIL_FROM (connexion@optizzz.fr) :"
write_env EMAIL_FROM "$EMAIL_FROM"
ask_secret DISCORD_REMINDERS_KEY "DISCORD_REMINDERS_KEY (la même, sinon les rappels enregistrés ne se lisent plus) :"
write_env DISCORD_REMINDERS_KEY "$DISCORD_REMINDERS_KEY"
ask NEXT_PUBLIC_ADSENSE_CLIENT "NEXT_PUBLIC_ADSENSE_CLIENT (vide si aucune) :"
write_env NEXT_PUBLIC_ADSENSE_CLIENT "$NEXT_PUBLIC_ADSENSE_CLIENT"
ask NEXT_PUBLIC_ADSENSE_SLOT "NEXT_PUBLIC_ADSENSE_SLOT (vide si aucune) :"
write_env NEXT_PUBLIC_ADSENSE_SLOT "$NEXT_PUBLIC_ADSENSE_SLOT"

stage "Scaleway : le stockage des sauvegardes"
say "Chaque nuit, une copie de la base part dans un bucket Object Storage (Paris), gardée 30 jours."
note "Sans bucket, les sauvegardes restent sur le VPS seulement (7 jours) : elles disparaîtraient avec lui."
if confirm "Mettre en place le bucket ?"; then
  open_url "https://console.scaleway.com/object-storage/buckets"
  step "Create bucket → région Paris, nom par exemple optizzz-backups, visibilité privée."
  ask BACKUP_BUCKET "Nom du bucket :"
  write_env BACKUP_BUCKET "$BACKUP_BUCKET"
  open_url "https://console.scaleway.com/iam/api-keys"
  step "Generate API key → pour une application IAM limitée à ObjectStorageFullAccess sur ce projet."
  ask SCW_ACCESS_KEY "Access key :"
  write_env SCW_ACCESS_KEY "$SCW_ACCESS_KEY"
  ask_secret SCW_SECRET_KEY "Secret key :"
  write_env SCW_SECRET_KEY "$SCW_SECRET_KEY"
else
  SKIPPED+=("bucket des sauvegardes : BACKUP_BUCKET, SCW_ACCESS_KEY, SCW_SECRET_KEY dans /opt/optizzz/.env")
fi

stage "Envoyer la configuration sur le VPS"
say "/opt/optizzz/.env (lisible par optizzz seul) et les fichiers de deploy/."
if confirm "Envoyer maintenant ?"; then
  {
    echo "TAG=none"
    for name in POSTGRES_PASSWORD APP_DB_PASSWORD REVALIDATE_SECRET BETTER_AUTH_SECRET BREVO_API_KEY EMAIL_FROM \
      DISCORD_REMINDERS_KEY BACKUP_BUCKET SCW_ACCESS_KEY SCW_SECRET_KEY; do
      echo "$name=$(_existing "$name" || true)"
    done
  } | deployer 'umask 077 && cat >/opt/optizzz/.env'
  scp -i "$DEPLOY_KEY" -r deploy/compose.yml deploy/Caddyfile deploy/deploy.sh deploy/ingest.sh deploy/backup.sh \
    deploy/postgres deploy/systemd "optizzz@$VPS_HOST:/opt/optizzz/" >/dev/null
  say "Envoyé."
else
  SKIPPED+=("envoyer /opt/optizzz/.env et deploy/ (étape 6)")
fi
pause

stage "Reprendre la base de Neon"
say "Tout passe : relevés des serveurs, comptes, espaces, rappels. Le site sur Vercel continue en attendant."
warn "Ce qui sera écrit sur Neon après cette copie (nouveaux comptes, Envois) ne suivra pas : enchaînez jusqu'au DNS."
note "Les relevés, eux, se rattrapent : chaque passage du cron reprend 10 jours d'historique."
NEON_URL=$(old DATABASE_URL)
if [[ -n "$NEON_URL" ]] && confirm "Copier Neon vers le VPS maintenant ?"; then
  # pg_dump wants Neon's direct endpoint, not its pooler.
  NEON_DIRECT=${NEON_URL/-pooler./.}
  # ssh hands its arguments to a shell: the URL is quoted for it.
  deployer bash -s -- "$(printf '%q' "$NEON_DIRECT")" <<'REMOTE'
set -euo pipefail
cd /opt/optizzz
docker compose up -d --wait db
docker compose exec -T db pg_dump "$1" --format=custom --no-owner --no-privileges >neon.dump
docker compose exec -T db pg_restore -U optizzz -d optizzz --no-owner --no-privileges <neon.dump ||
  echo "pg_restore a signalé des erreurs (ci-dessus) : vérifiez-les avant de continuer."
docker compose exec -T db psql -U optizzz -d optizzz -v ON_ERROR_STOP=1 --quiet <postgres/grants.sql
docker compose exec -T db psql -U optizzz -d optizzz -tc 'SELECT count(*) || '' comptes'' FROM accounts."user"'
REMOTE
else
  SKIPPED+=("copie de Neon (étape 7) : DATABASE_URL du propriétaire introuvable dans $OLD_ENV, ou reportée")
fi
pause

stage "GitHub : le déploiement"
say "Le workflow « Deploy » construit les images, puis lance deploy.sh sur le VPS par SSH."
set_secret VPS_HOST "$VPS_HOST"
set_secret VPS_SSH_KEY "$(cat "$DEPLOY_KEY")"
set_secret VPS_KNOWN_HOSTS "$(ssh-keyscan -t ed25519 "$VPS_HOST" 2>/dev/null)"
[[ -n "$(_existing NEXT_PUBLIC_ADSENSE_CLIENT || true)" ]] && set_var NEXT_PUBLIC_ADSENSE_CLIENT "$(_existing NEXT_PUBLIC_ADSENSE_CLIENT)"
[[ -n "$(_existing NEXT_PUBLIC_ADSENSE_SLOT || true)" ]] && set_var NEXT_PUBLIC_ADSENSE_SLOT "$(_existing NEXT_PUBLIC_ADSENSE_SLOT)"
step "Poussez sur main le commit qui ajoute deploy/ (ou : gh workflow run deploy.yml), puis suivez-le : gh run watch."
step "Au premier passage, rendez publics les deux paquets créés (le VPS les télécharge sans jeton) :"
open_url "https://github.com/Achaak?tab=packages&repo_name=Optizzz"
note "  optizzz-web et optizzz-tools → Package settings → Change visibility → Public."
note "Si le job « deploy » a échoué faute d'accès aux images : relancez-le (gh run rerun --failed)."
pause "Déployé ? Entrée pour continuer"

stage "Le cron horaire et la sauvegarde de nuit"
say "Deux minuteries systemd : ingest.sh à chaque heure et dix, backup.sh à 3 h 40 (UTC)."
if confirm "Les installer maintenant ?"; then
  root 'install -m 644 /opt/optizzz/systemd/* /etc/systemd/system/ && systemctl daemon-reload &&
    systemctl enable --now optizzz-ingest.timer optizzz-backup.timer && systemctl list-timers "optizzz-*"'
  if confirm "Lancer un premier relevé et une première sauvegarde pour vérifier ?"; then
    root 'systemctl start optizzz-ingest.service optizzz-backup.service; journalctl -u "optizzz-*" -n 20 --no-pager'
  fi
else
  SKIPPED+=("minuteries : install -m 644 /opt/optizzz/systemd/* /etc/systemd/system/ && systemctl enable --now optizzz-ingest.timer optizzz-backup.timer")
fi
pause

stage "Le domaine optizzz.fr"
say "Caddy demande le certificat HTTPS tout seul dès que le domaine pointe vers le VPS."
step "Chez votre registraire, remplacez les enregistrements de Vercel :"
note "  optizzz.fr      A      $VPS_HOST"
note "  www.optizzz.fr  CNAME  optizzz.fr."
note "  (et un AAAA vers l'IPv6 de l'instance si elle en a une ; supprimez les anciens A et CNAME de Vercel)"
step "Attendez la propagation : dig +short optizzz.fr doit donner $VPS_HOST."
step "Vérifiez : curl -sI https://optizzz.fr | head -1 (HTTP/2 200), puis une connexion par lien magique."
pause "Le site répond depuis le VPS ? Entrée pour continuer"

stage "Ranger l'ancienne installation"
say "Une fois le VPS en place depuis quelques jours (relevés horaires, sauvegardes dans le bucket) :"
step "Vercel : projet optizzz → Settings → Advanced → Delete Project (le domaine part avec)."
step "Neon : le projet optizzz → Settings → Delete project."
step "GitHub : les secrets de l'ancien cron ne servent plus."
if confirm "Supprimer maintenant les secrets DATABASE_URL, REVALIDATE_SECRET et la variable SITE_URL de GitHub ?"; then
  gh secret delete DATABASE_URL || true
  gh secret delete REVALIDATE_SECRET || true
  gh variable delete SITE_URL || true
else
  SKIPPED+=("GitHub : gh secret delete DATABASE_URL ; gh secret delete REVALIDATE_SECRET ; gh variable delete SITE_URL")
fi
note "$OLD_ENV peut alors partir aussi, une fois ses secrets recopiés ici ($ENV_FILE)."
pause

finish
